  @spec var collection_proposal: EIT_Acquisition_Supervisor.Proposal.Type = $

  def put_collection_proposal(value : EIT_Acquisition_Supervisor.Proposal.Type) : Unit = {
    Contract(
      Modifies(collection_proposal),
      Ensures(
        collection_proposal == value
      )
